  "decision_target": "eligibility for Gift Aid",
  "decision_unit": "one donation",
  "eligibility_expression": {
    "ref": "a1"
  },
  "limitations": [
    "The donor's tax year evidence is not available for the donation made in 2026, and the Gift Aid declaration is incomplete, so the truth of the tax and declaration conditions cannot be verified.",
    "The policy does not specify whether donations from individuals are only eligible if the donor is a charity or CASC; this is not explicitly stated, and the donor must be recognised as a charity or CASC for tax purposes (E02), which is a separate condition."
  ],
  "scope_issues": [
    "The policy applies to donations from individuals, but does not specify whether donations from individuals who are not recognised as charities or CASC are eligible. The decision target is per donation, but the policy may not cover all types of donations or donors."
  ]
